11	/*!
12	 * \file add_example.h
13	 * \brief Add算子Kernel实现，实现向量逐元素相加操作 z = x + y
14	 */
15	#ifndef ADD_EXAMPLE_H
16	#define ADD_EXAMPLE_H
17	
18	#include "kernel_operator.h"
19	#include "kernel_tiling/kernel_tiling.h"
20	#include "add_example_tiling_data.h"
21	#include "add_example_tiling_key.h"
22	
23	namespace NsAddExample {
24	
25	using namespace AscendC;
26	
27	constexpr int32_t BUFFER_NUM = 2;
28	
29	template <typename T>
30	class AddExample {
31	public:
32	    __aicore__ inline AddExample(){};
33	
34	    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y, GM_ADDR z, const AddExampleTilingData* tilingData);
35	    __aicore__ inline void Process();
36	
37	private:
38	    __aicore__ inline void CopyIn(int64_t progress, int64_t currentNum);
39	    __aicore__ inline void CopyOut(int64_t progress, int64_t currentNum);
40	    __aicore__ inline void Compute(int64_t currentNum);
41	
42	private:
43	    TPipe pipe;
44	    TQue<QuePosition::VECIN, BUFFER_NUM> inputQueueX;
45	    TQue<QuePosition::VECIN, BUFFER_NUM> inputQueueY;
46	    TQue<QuePosition::VECOUT, BUFFER_NUM> outputQueueZ;
47	
48	    GlobalTensor<T> inputGMX;
49	    GlobalTensor<T> inputGMY;
50	    GlobalTensor<T> outputGMZ;
51	
52	    int64_t blockLength_ = 0;
53	    int64_t ubLength_ = 0;
54	};
55	
56	template <typename T>
57	__aicore__ inline void AddExample<T>::Init(GM_ADDR x, GM_ADDR y, GM_ADDR z, const AddExampleTilingData* tilingData)
58	{
59	    int64_t remainderLength = tilingData->totalNum - tilingData->blockFactor * (AscendC::GetBlockIdx() - 1);
60	    blockLength_ = (remainderLength > tilingData->blockFactor) ? tilingData->blockFactor : remainderLength;
61	    ubLength_ = tilingData->ubFactor;
62	
63	    inputGMX.SetGlobalBuffer((__gm__ T*)x + tilingData->blockFactor * AscendC::GetBlockIdx(), blockLength_);
64	    inputGMY.SetGlobalBuffer((__gm__ T*)y + tilingData->blockFactor * AscendC::GetBlockIdx(), blockLength_);
65	    outputGMZ.SetGlobalBuffer((__gm__ T*)z + tilingData->blockFactor * AscendC::GetBlockIdx(), blockLength_);
66	
67	    pipe.InitBuffer(inputQueueX, BUFFER_NUM, ubLength_ * sizeof(T));
68	    pipe.InitBuffer(inputQueueY, BUFFER_NUM, ubLength_ * sizeof(T));
69	    pipe.InitBuffer(outputQueueZ, BUFFER_NUM, ubLength_ * sizeof(T));
70	}
71	
72	template <typename T>
73	__aicore__ inline void AddExample<T>::CopyIn(int64_t progress, int64_t currentNum)
74	{
75	    AscendC::LocalTensor<T> xLocal = inputQueueX.AllocTensor<T>();
76	    AscendC::LocalTensor<T> yLocal = inputQueueY.AllocTensor<T>();
77	    AscendC::DataCopyParams copyParams;
78	    copyParams.blockCount = 1;
79	    copyParams.blockLen = currentNum * sizeof(T);
80	    copyParams.srcStride = 0;
81	    copyParams.dstStride = 0;
82	    AscendC::DataCopyPad(xLocal, inputGMX[progress * ubLength_], copyParams, {false, 0, 0, 0});
83	    AscendC::DataCopyPad(yLocal, inputGMY[progress * ubLength_], copyParams, {false, 0, 0, 0});
84	    inputQueueX.EnQue(xLocal);
85	    inputQueueY.EnQue(yLocal);
86	}
87	
88	template <typename T>
89	__aicore__ inline void AddExample<T>::CopyOut(int64_t progress, int64_t currentNum)
90	{
91	    AscendC::LocalTensor<T> zLocal = outputQueueZ.DeQue<T>();
92	    AscendC::DataCopyParams copyParams;
93	    copyParams.blockCount = 1;
94	    copyParams.blockLen = currentNum * sizeof(T);
95	    copyParams.srcStride = 0;
96	    copyParams.dstStride = 0;
97	    AscendC::DataCopyPad(outputGMZ[progress * ubLength_], zLocal, copyParams);
98	    outputQueueZ.FreeTensor(zLocal);
99	}
100	
101	template <typename T>
102	__aicore__ inline void AddExample<T>::Compute(int64_t currentNum)
103	{
104	    AscendC::LocalTensor<T> xLocal = inputQueueX.DeQue<T>();
105	    AscendC::LocalTensor<T> yLocal = inputQueueY.DeQue<T>();
106	    AscendC::LocalTensor<T> zLocal = outputQueueZ.AllocTensor<T>();
107	    AscendC::Add(zLocal, xLocal, yLocal, currentNum);
108	    outputQueueZ.EnQue<T>(zLocal);
109	    inputQueueX.FreeTensor(xLocal);
110	    inputQueueY.FreeTensor(yLocal);
111	}
112	
113	template <typename T>
114	__aicore__ inline void AddExample<T>::Process()
115	{
116	    int64_t loopCount = (blockLength_ + ubLength_ - 1) / ubLength_;
117	    for (int64_t i = 0; i < loopCount; i++) {
118	        int64_t currentNum = (i == (loopCount - 1)) ? (blockLength_ - ubLength_ * i) : ubLength_;
119	        CopyIn(i, currentNum);
120	        Compute(currentNum);
121	        CopyOut(i, currentNum);
122	    }
123	}
124	
125	} // namespace NsAddExample
126	#endif // ADD_EXAMPLE_H
